package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.knowledge.KnowledgeSource;import com.learnagent.rag.*;import java.util.*;import org.springframework.ai.document.Document;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class KnowledgeSkill{private final LocalKnowledgeService service;private final SourceMapper mapper;private final AgentExecutionTracker tracker;public KnowledgeSkill(LocalKnowledgeService service,SourceMapper mapper,AgentExecutionTracker tracker){this.service=service;this.mapper=mapper;this.tracker=tracker;}@Tool(description="Search only the selected course's local PDF knowledge base. Use for questions about course materials.")public List<KnowledgeResult> searchLocalKnowledge(@ToolParam(description="Course ID whose documents may be searched")UUID courseId,@ToolParam(description="Semantic search query")String query){return tracker.execute("Knowledge Skill","searchLocalKnowledge",()->{List<Document> documents=service.search(courseId,query);List<RagSource> sources=mapper.mapAndDeduplicate(documents);tracker.addSources(sources.stream().map(source->KnowledgeSource.local(source.documentId(),source.filename(),source.pageNumber(),source.snippet())).toList());return documents.stream().map(document->new KnowledgeResult(document.getText(),String.valueOf(document.getMetadata().get("filename")),page(document),UUID.fromString(String.valueOf(document.getMetadata().get("documentId"))))).toList();},values->"Retrieved "+values.size()+" course excerpts");}private Integer page(Document document){Object value=document.getMetadata().get("pageNumber");return value instanceof Number n?n.intValue():null;}public record KnowledgeResult(String content,String filename,Integer pageNumber,UUID documentId){}}
